package de.corporate.lc.imports.api;
import de.corporate.lc.audit.service.AuditService; import de.corporate.lc.document.service.DocumentExtractionService; import de.corporate.lc.imports.domain.SwiftImportRecord; import de.corporate.lc.imports.service.*; import de.corporate.lc.swift.PrintedSwiftNormalizer; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.util.List;
@RestController @RequestMapping("/api/imports") public class SwiftImportController {private final SwiftImportService service;private final SwiftImportHistoryService history;private final AuditService audit;private final DocumentExtractionService extraction;private final PrintedSwiftNormalizer normalizer;public SwiftImportController(SwiftImportService s,SwiftImportHistoryService h,AuditService a,DocumentExtractionService e,PrintedSwiftNormalizer n){service=s;history=h;audit=a;extraction=e;normalizer=n;}@PostMapping("/preview")public SwiftImportPreview preview(@RequestBody SwiftImportRequest r){return service.preview(r);}@PostMapping("/file-preview")public SwiftFilePreview filePreview(@RequestPart("file")MultipartFile file)throws IOException{if(file.isEmpty())throw new IllegalArgumentException("Die Datei ist leer.");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Die Datei ist größer als 10 MB.");var result=extraction.extractFile(file.getBytes(),file.getOriginalFilename(),file.getContentType());if(result.text()==null||result.text().isBlank())throw new IllegalArgumentException("Aus dem PDF konnte kein Text erkannt werden.");String normalized=normalizer.normalize(result.text());SwiftImportRequest request=new SwiftImportRequest(file.getOriginalFilename(),normalized.isBlank()?result.text():normalized);return new SwiftFilePreview(request,service.preview(request),result.status());}@PostMapping public Object execute(@RequestBody SwiftImportRequest r,Authentication a){Object result=service.execute(r);audit.record(a,"SWIFT_IMPORTED","IMPORT",null,r.filename());return result;}@GetMapping public List<SwiftImportRecord> recent(){return history.recent();}}
